// ================================================================================================
// [РАЗМЕТКА ФАЗ -- МАСКА БИТОВ, а не одно число]
// ================================================================================================
// ЗАЧЕМ. Одним числом (DIAG) снимается РОВНО ОДНА фаза, поэтому из замера восстанавливаются только
// доли s_i. Невязка 1 - SUM(s_i) при этом НЕ РАЗДЕЛЕНА: в ней сидят и ПЕРЕКРЫТИЕ фаз, и работа,
// которую ни одна фаза не назвала. Разделяет её только маска:
//
//     1 = SUM(s_i) + (s_all - SUM(s_i)) + (1 - s_all)
//         названное      ПЕРЕКРЫТИЕ        НЕНАЗВАННОЕ          поточечно: e_ij = s_ij - s_i - s_j
//
// БИТЫ (нумерация подряд с нуля -- требование tools/phaseprof.py scan):
//     бит 0  gemm1   первое умножение  Q*K^T   (s.accumulate_bi8)          прежний DIAG=5
//     бит 1  gemm2   второе умножение  P*V     (o.accumulate_bi8)          прежний DIAG=3
//     бит 2  softmax максимум/exp2/редукции суммы (P становится 0.5+S)     прежний DIAG=1
//     бит 3  feed    перекладка байтов K/V везущими варпами (LDG+STS)      прежний DIAG=4
//     бит 4  rendez  два внутренних рандеву считающих (bar.sync 3)         прежний DIAG=2
// Маска 31 = снять ВСЕ ПЯТЬ. Все 10 пар лежат в том же диапазоне 0..31.
//
// КАК ПРИХОДИТ МАСКА -- ДВУМЯ ПУТЯМИ, И ОНИ СОГЛАСОВАНЫ:
//   1. макросом -DFMHA_STRIP_MASK=N при сборке -- ровно то, что подставляет tools/phaseprof.py
//      в свою строку сборки (см. tools/fmha_phase.h). Действует на ВСЕ инстанцирования сразу.
//   2. шаблонным параметром DIAG кодами 64..95 (DIAG = 64 + mask) -- позволяет держать всё
//      семейство из 32 вариантов в ОДНОЙ отгруженной библиотеке и выбирать номером nosc, без
//      пересборки. Из хоста это варианты nosc/100 = 40..71 (см. attn_fwd_cutlass.cu).
// ПОЧЕМУ НЕ НОВЫЙ ПАРАМЕТР В КОНЕЦ СПИСКА. Новый параметр меняет УКРАШЕННОЕ ИМЯ всех прежних
// инстанцирований, а значит и заголовок функции в SASS: побайтового равенства с боевой сборкой
// уже не доказать. Кодами внутри существующего параметра список не трогается вовсе, и A/B даёт
// РАВЕНСТВО ВКЛЮЧАЯ ИМЯ. Диапазон 6..63 оставлен свободным под будущие одиночные фальсификаторы.
// Итоговое kStrip = маска | бит прежнего DIAG, поэтому старые одиночные коды продолжают работать
// БЕЗ ЕДИНОГО ИЗМЕНЕНИЯ SASS (проверено компиляционным A/B на всех шести: DIAG=0..5).
//
// ПЛОМБЫ И СТОКИ. Насильный потребитель (сток) в семействе маски по умолчанию ВЫКЛЮЧЕН -- почему
// именно так, сказано у FA2_WS_SINK ниже: замер невязок показал, что каскада, ради которого он
// строился, в этом ядре НЕТ. Стоком служит УЖЕ ИМЕЮЩАЯСЯ константа kFakeXorMask (== 0, но
// компилятор не вправе её свернуть) -- поэтому даже включённым он не добавляет боевой сборке ни
// одного нового символа и ни байта постоянной памяти.
#ifndef FMHA_STRIP_MASK
#define FMHA_STRIP_MASK 0u
#endif
// [НАСИЛЬНЫЙ ПОТРЕБИТЕЛЬ -- ПО УМОЛЧАНИЮ ВЫКЛЮЧЕН, И ЭТО РЕЗУЛЬТАТ ЗАМЕРА, А НЕ ЛЕНЬ]
// Он строился против каскада «сняли ОБА умножения -> умерла ОБЩАЯ адресация плитки -> в паре
// пропала работа, которой нет ни в одном одиночном снятии». Каскад ПРОВЕРЕН статически на всех
// 32 масках (счёт команд SASS, невязка e_ij = c(i|j) - c(i) - c(j) + c(0)) и НЕ ОБНАРУЖЕН:
// по HMMA, LDS, STS, LDG, MUFU, SHFL, BAR и PRMT невязка РОВНО НОЛЬ у всех десяти пар и у
// «всех пяти», И СО СТОКОМ, И БЕЗ НЕГО. Сток при этом стоит +1 STG и ухудшает невязку пары
// умножений по TOTAL с 0 до +8. Правило проекта: рычаг, давший ноль, ОТКАТЫВАТЬ.
// Выключенный сток даёт вдобавок главное свойство совместимости: одиночные маски 1/2/4/8/16
// собираются В ТЕ ЖЕ КОМАНДЫ, что прежние DIAG=5/3/1/4/2, то есть уже снятые доли
// 35.1/19.7/15.2/5.7/2.0 % подставляются в баланс без перезамера.
// FA2_WS_SINK=1 -- включить обратно (код сохранён, потому что каскад зависит от РАСКЛАДКИ кода:
// при следующей перестановке мейнлупа проверку надо повторить, а не унаследовать вывод).
#ifndef FA2_WS_SINK
#define FA2_WS_SINK 0
#endif
// Имена -- как в tools/fmha_phase.h (их ищет `phaseprof.py scan`), но условие берётся из
// ЛОКАЛЬНОГО kStrip: он уже вобрал и макрос FMHA_STRIP_MASK, и код маски в DIAG. Тело фазы -- в
// фигурных скобках сразу за макросом.
// [ПОЧЕМУ push_macro/pop_macro, А НЕ #ifndef] Те же имена определяет fa2_src/fmha_kernel/fwd_phase.h
// (разметка ДРУГОГО форварда, cutlass-ного), и attn_fwd_cutlass.cu включает оба заголовка. При
// голом #ifndef смысл макроса зависел бы от ПОРЯДКА ВКЛЮЧЕНИЯ: переставили строки -- и наша
// маска молча превратилась в `if constexpr (true)`, то есть фальсификатор стал бы боевым путём
// без единого признака. Здесь имена берутся взаймы на время этого заголовка и возвращаются в
// конце файла ровно теми, какими были.
#pragma push_macro("FMHA_PHASE")
#pragma push_macro("FMHA_PHASE_ELSE")
#pragma push_macro("FMHA_PHASE_ON")
#pragma push_macro("FMHA_PHASE_OFF")
#pragma push_macro("FMHA_SEAL_W32")
#pragma push_macro("FMHA_SEAL")
#pragma push_macro("FMHA_SINK")
#undef FMHA_PHASE
#undef FMHA_PHASE_ELSE
#undef FMHA_PHASE_ON
#undef FMHA_PHASE_OFF
#undef FMHA_SEAL_W32
#undef FMHA_SEAL
#undef FMHA_SINK
#define FMHA_PHASE(name, id)      if constexpr (!((kStrip) & (1u << (id))))
#define FMHA_PHASE_ELSE(name, id) else
#define FMHA_PHASE_ON(id)         (!((kStrip) & (1u << (id))))
#define FMHA_PHASE_OFF(id)        (((kStrip) & (1u << (id))) != 0u)
// ПЛОМБА: одна команда SASS, тождественная побитово (prmt с селектором 0x3210 возвращает источник
// как есть). Пустая вставка asm("") ЗДЕСЬ НЕ ГОДИТСЯ -- ptxas сворачивает сквозь неё, и барьер
// подтверждается только по SASS, а не по PTX.
#define FMHA_SEAL_W32(w) asm volatile("prmt.b32 %0, %0, %0, 0x3210;" : "+r"(w))
// СТОК: заставляет ВЫЧИСЛЕНИЕ состояться, даже если результат никем не читается. Условие
